857	    }
858	
859	    // printf("POC: %d\n", ps_slice_hdr->i4_abs_pic_order_cnt);
860	    // AEV_TRACE("POC", ps_slice_hdr->i4_abs_pic_order_cnt, 0);
861	    ps_slice_hdr->i4_num_entry_point_offsets = 0;
862	    if((ps_pps->i1_tiles_enabled_flag) ||
863	       (ps_pps->i1_entropy_coding_sync_enabled_flag))
864	    {
865	        UEV_PARSE("num_entry_point_offsets", value, ps_bitstrm);
866	        ps_slice_hdr->i4_num_entry_point_offsets = value;
867	
868	        {
869	            WORD32 max_num_entry_point_offsets;
870	            if((ps_pps->i1_tiles_enabled_flag) &&
871	                            (ps_pps->i1_entropy_coding_sync_enabled_flag))
872	            {
873	                max_num_entry_point_offsets = ps_pps->i1_num_tile_columns * ps_sps->i2_pic_ht_in_ctb - 1;
874	            }
875	            else if(ps_pps->i1_tiles_enabled_flag)
876	            {
877	                max_num_entry_point_offsets = ps_pps->i1_num_tile_columns * ps_pps->i1_num_tile_rows - 1 ;
878	            }
879	            else
880	            {
881	                max_num_entry_point_offsets = (ps_sps->i2_pic_ht_in_ctb - 1);
882	            }
883	
884	            if(ps_slice_hdr->i4_num_entry_point_offsets < 0 || ps_slice_hdr->i4_num_entry_point_offsets > max_num_entry_point_offsets)
885	            {
886	                return IHEVCD_INVALID_PARAMETER;
887	            }
888	        }
889	
890	        if(ps_slice_hdr->i4_num_entry_point_offsets > 0)
891	        {
892	            UEV_PARSE("offset_len_minus1", value, ps_bitstrm);
893	            if(value > 31)
894	            {
895	                return IHEVCD_INVALID_PARAMETER;
896	            }
897	            ps_slice_hdr->i1_offset_len = value + 1;
898	
899	            for(i = 0; i < ps_slice_hdr->i4_num_entry_point_offsets; i++)
900	            {
901	                BITS_PARSE("entry_point_offset", value, ps_bitstrm, ps_slice_hdr->i1_offset_len);
902	
903	                /* TODO: pu4_entry_point_offset needs to be initialized */
904	                //ps_slice_hdr->pu4_entry_point_offset[i] = value;
905	            }
906	
907	        }
908	    }
909	
910	    if(ps_pps->i1_slice_header_extension_present_flag)
911	    {
912	        UEV_PARSE("slice_header_extension_length", value, ps_bitstrm);
913	        if(value > 256)
914	        {
915	            return IHEVCD_INVALID_PARAMETER;
916	        }
917	        ps_slice_hdr->i2_slice_header_extension_length = value;
918	
919	
920	        for(i = 0; i < ps_slice_hdr->i2_slice_header_extension_length; i++)
921	        {
922	            BITS_PARSE("slice_header_extension_data_byte", value, ps_bitstrm, 8);
923	        }
924	
925	    }
926	
927	    ihevcd_bits_flush_to_byte_boundary(ps_bitstrm);
928	
929	    if((UWORD8 *)ps_bitstrm->pu4_buf > ps_bitstrm->pu1_buf_max)
930	        return IHEVCD_INVALID_PARAMETER;
931	
932	    {
933	        dpb_mgr_t *ps_dpb_mgr = (dpb_mgr_t *)ps_codec->pv_dpb_mgr;
934	        WORD32 r_idx;
935	
936	        if((NAL_IDR_W_LP == ps_slice_hdr->i1_nal_unit_type) ||
937	                        (NAL_IDR_N_LP == ps_slice_hdr->i1_nal_unit_type)  ||
938	                        (NAL_BLA_N_LP == ps_slice_hdr->i1_nal_unit_type)  ||
939	                        (NAL_BLA_W_DLP == ps_slice_hdr->i1_nal_unit_type) ||
940	                        (NAL_BLA_W_LP == ps_slice_hdr->i1_nal_unit_type)  ||
941	                        (0 == ps_codec->u4_pic_cnt))
942	        {
943	            for(i = 0; i < MAX_DPB_BUFS; i++)
944	            {
945	                if(ps_dpb_mgr->as_dpb_info[i].ps_pic_buf)
946	                {
947	                    pic_buf_t *ps_pic_buf = ps_dpb_mgr->as_dpb_info[i].ps_pic_buf;
948	                    mv_buf_t *ps_mv_buf;
949	
950	                    /* Long term index is set to MAX_DPB_BUFS to ensure it is not added as LT */
951	                    ihevc_dpb_mgr_del_ref((dpb_mgr_t *)ps_codec->pv_dpb_mgr, (buf_mgr_t *)ps_codec->pv_pic_buf_mgr, ps_pic_buf->i4_abs_poc);
952	                    /* Find buffer id of the MV bank corresponding to the buffer being freed (Buffer with POC of u4_abs_poc) */
953	                    ps_mv_buf = (mv_buf_t *)ps_codec->ps_mv_buf;
954	                    for(j = 0; j < ps_codec->i4_max_dpb_size; j++)
955	                    {
956	                        if(ps_mv_buf && ps_mv_buf->i4_abs_poc == ps_pic_buf->i4_abs_poc)
957	                        {
958	                            ihevc_buf_mgr_release((buf_mgr_t *)ps_codec->pv_mv_buf_mgr, j, BUF_MGR_REF);
959	                            break;
960	                        }
961	                        ps_mv_buf++;
962	                    }
963	
964	                }
965	
966	            }
967	
968	            /* Initialize the reference lists to NULL
969	             * This is done to take care of the cases where the first pic is not IDR
970	             * but the reference list is not created for the first pic because
971	             * pic count is zero leaving the reference list uninitialised  */
972	            for(r_idx = 0; r_idx < MAX_DPB_SIZE; r_idx++)
973	            {
974	                ps_slice_hdr->as_ref_pic_list0[r_idx].pv_pic_buf = NULL;
975	                ps_slice_hdr->as_ref_pic_list0[r_idx].pv_mv_buf = NULL;
976	
977	                ps_slice_hdr->as_ref_pic_list1[r_idx].pv_pic_buf = NULL;
978	                ps_slice_hdr->as_ref_pic_list1[r_idx].pv_mv_buf = NULL;
979	            }
980	
981	        }
982	        else
983	        {
984	            ret = ihevcd_ref_list(ps_codec, ps_pps, ps_sps, ps_slice_hdr);
985	            if ((WORD32)IHEVCD_SUCCESS != ret)
986	            {
987	                return ret;
988	            }
989	
990	        }
991	
992	    }
993	
994	    /* Fill the remaining entries of the reference lists with the nearest POC
995	     * This is done to handle cases where there is a corruption in the reference index */
996	    if(ps_codec->i4_pic_present)
997	    {
998	        pic_buf_t *ps_pic_buf_ref;
999	        mv_buf_t *ps_mv_buf_ref;
1000	        WORD32 r_idx;
1001	        dpb_mgr_t *ps_dpb_mgr = (dpb_mgr_t *)ps_codec->pv_dpb_mgr;
1002	        buf_mgr_t *ps_mv_buf_mgr = (buf_mgr_t *)ps_codec->pv_mv_buf_mgr;
1003	
1004	        ps_pic_buf_ref = ihevc_dpb_mgr_get_ref_by_nearest_poc(ps_dpb_mgr, ps_slice_hdr->i4_abs_pic_order_cnt);
1005	        if(NULL == ps_pic_buf_ref)
1006	        {
1007	            ps_pic_buf_ref = ps_codec->as_process[0].ps_cur_pic;
1008	            ps_mv_buf_ref = ps_codec->s_parse.ps_cur_mv_buf;
1009	        }
1010	        else
1011	        {
1012	            ps_mv_buf_ref = ihevcd_mv_mgr_get_poc(ps_mv_buf_mgr, ps_pic_buf_ref->i4_abs_poc);
1013	        }
1014	
1015	        for(r_idx = 0; r_idx < ps_slice_hdr->i1_num_ref_idx_l0_active; r_idx++)
1016	        {
1017	            if(NULL == ps_slice_hdr->as_ref_pic_list0[r_idx].pv_pic_buf)
1018	            {
1019	                ps_slice_hdr->as_ref_pic_list0[r_idx].pv_pic_buf = (void *)ps_pic_buf_ref;
1020	                ps_slice_hdr->as_ref_pic_list0[r_idx].pv_mv_buf = (void *)ps_mv_buf_ref;
1021	            }
1022	        }
1023	
1024	        for(r_idx = ps_slice_hdr->i1_num_ref_idx_l0_active; r_idx < MAX_DPB_SIZE; r_idx++)
1025	        {
1026	            ps_slice_hdr->as_ref_pic_list0[r_idx].pv_pic_buf = (void *)ps_pic_buf_ref;
1027	            ps_slice_hdr->as_ref_pic_list0[r_idx].pv_mv_buf = (void *)ps_mv_buf_ref;
1028	        }
1029	
1030	        for(r_idx = 0; r_idx < ps_slice_hdr->i1_num_ref_idx_l1_active; r_idx++)
1031	        {
1032	            if(NULL == ps_slice_hdr->as_ref_pic_list1[r_idx].pv_pic_buf)
1033	            {
1034	                ps_slice_hdr->as_ref_pic_list1[r_idx].pv_pic_buf = (void *)ps_pic_buf_ref;
1035	                ps_slice_hdr->as_ref_pic_list1[r_idx].pv_mv_buf = (void *)ps_mv_buf_ref;
1036	            }
1037	        }
1038	
1039	        for(r_idx = ps_slice_hdr->i1_num_ref_idx_l1_active; r_idx < MAX_DPB_SIZE; r_idx++)
1040	        {
1041	            ps_slice_hdr->as_ref_pic_list1[r_idx].pv_pic_buf = (void *)ps_pic_buf_ref;
1042	            ps_slice_hdr->as_ref_pic_list1[r_idx].pv_mv_buf = (void *)ps_mv_buf_ref;
1043	        }
1044	    }
1045	
1046	    /* Update slice address in the header */
1047	    if(!ps_slice_hdr->i1_first_slice_in_pic_flag)
1048	    {
1049	        ps_slice_hdr->i2_ctb_x = slice_address % ps_sps->i2_pic_wd_in_ctb;
1050	        ps_slice_hdr->i2_ctb_y = slice_address / ps_sps->i2_pic_wd_in_ctb;
1051	
1052	        if(!ps_slice_hdr->i1_dependent_slice_flag)
1053	        {
1054	            ps_slice_hdr->i2_independent_ctb_x = ps_slice_hdr->i2_ctb_x;
1055	            ps_slice_hdr->i2_independent_ctb_y = ps_slice_hdr->i2_ctb_y;
1056	        }
1057	    }
1058	    else
1059	    {
1060	        ps_slice_hdr->i2_ctb_x = 0;
1061	        ps_slice_hdr->i2_ctb_y = 0;
1062	
1063	        ps_slice_hdr->i2_independent_ctb_x = 0;
1064	        ps_slice_hdr->i2_independent_ctb_y = 0;
1065	    }
1066	
1067	    /* If the first slice in the pic is missing, copy the current slice header to
1068	     * the first slice's header */
1069	    if((!first_slice_in_pic_flag) &&
1070	                    (0 == ps_codec->i4_pic_present))
1071	    {
1072	        slice_header_t *ps_slice_hdr_prev = ps_codec->s_parse.ps_slice_hdr_base;
1073	        ihevcd_copy_slice_hdr(ps_codec, 0, (ps_codec->s_parse.i4_cur_slice_idx & (MAX_SLICE_HDR_CNT - 1)));
1074	
1075	        prev_slice_incomplete_flag = 1;
1076	        ASSERT(ps_codec->s_parse.i4_cur_slice_idx == 1);
1077	
1078	        ps_slice_hdr_prev->i2_ctb_x = 0;
1079	        ps_slice_hdr_prev->i2_ctb_y = 0;
1080	
1081	        ps_codec->s_parse.i4_ctb_x = 0;
1082	        ps_codec->s_parse.i4_ctb_y = 0;
1083	
1084	        ps_codec->s_parse.i4_cur_slice_idx = 0;
1085	
1086	        if((ps_slice_hdr->i2_ctb_x == 0) &&
1087	                        (ps_slice_hdr->i2_ctb_y == 0))
1088	        {
1089	            ps_slice_hdr->i2_ctb_x++;
1090	        }
1091	    }
1092	
1093	    {
1094	        /* If skip B is enabled,
1095	         * ignore pictures that are non-reference
1096	         * TODO: (i1_nal_unit_type < NAL_BLA_W_LP) && (i1_nal_unit_type % 2 == 0) only says it is
1097	         * sub-layer non-reference slice. May need to find a way to detect actual non-reference pictures*/
1098	
1099	        if((i1_nal_unit_type < NAL_BLA_W_LP) &&
1100	                        (i1_nal_unit_type % 2 == 0))
1101	        {
1102	            if(IVD_SKIP_B == ps_codec->e_pic_skip_mode)
1103	                return IHEVCD_IGNORE_SLICE;
1104	        }
1105	
1106	        /* If skip PB is enabled,
1107	         * decode only I slices */
1108	        if((IVD_SKIP_PB == ps_codec->e_pic_skip_mode) &&
1109	                        (ISLICE != ps_slice_hdr->i1_slice_type))
1110	        {
1111	            return IHEVCD_IGNORE_SLICE;
1112	        }
1113	    }
1114	
1115	    if(prev_slice_incomplete_flag)
1116	    {
1117	        ps_codec->i4_slice_error = 1;
1118	        ps_codec->s_parse.i4_cur_slice_idx--;
1119	        if(ps_codec->s_parse.i4_cur_slice_idx < 0)
1120	            ps_codec->s_parse.i4_cur_slice_idx = 0;
1121	    }
1122	
1123	    return ret;
1124	}
